import { initializeApp } from 'firebase/app';
import { initializeAppCheck, ReCaptchaEnterpriseProvider } from 'firebase/app-check';

const firebaseConfig = {
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY || 'dummy_api_key',
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN || 'sentaient.firebaseapp.com',
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID || 'sentaient',
  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET || 'sentaient.appspot.com',
  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID || 'dummy_sender_id',
  appId: import.meta.env.VITE_FIREBASE_APP_ID || 'dummy_app_id'
};

const app = initializeApp(firebaseConfig);

// Initialize Firebase App Check with ReCAPTCHA Enterprise
// In development, you would set self.FIREBASE_APPCHECK_DEBUG_TOKEN = true
export const initAppCheck = () => {
  try {
    const appCheck = initializeAppCheck(app, {
      provider: new ReCaptchaEnterpriseProvider(import.meta.env.VITE_RECAPTCHA_SITE_KEY || 'dummy_recaptcha_key'),
      isTokenAutoRefreshEnabled: true
    });
    console.log('Firebase App Check initialized successfully.');
    return appCheck;
  } catch (error) {
    console.error('Failed to initialize Firebase App Check:', error);
  }
};
